window.kbPageData["views/entry/k-d3dd3aebd531fc45"] = {"key":"entry/k-d3dd3aebd531fc45","state":{"route":"entry/k-d3dd3aebd531fc45"},"node":{"id":"k-d3dd3aebd531fc45","mode":"k","title":"合作工程的分段计量","type":"方法与技能","domain":"数学","reading":"","intro":"","priority":100,"aliases":["工程量等于工作效率乘以时间，合作效率为各自实际效率之和"],"qs":["国考 2024 副省级 行测#72"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"每一段内效率恒定时，工作量等于该段效率乘以时间。各人同期完成的工作量可以相加时，合作效率等于各人在合作状态下的实际效率之和。","review":{"definition":"每一段内效率恒定时，工作量等于该段效率乘以时间。各人同期完成的工作量可以相加时，合作效率等于各人在合作状态下的实际效率之和。","explanation":"补全的题本显示，乙、丙15天完成第一段剩余量的2/3，占总量的1/2，末段乙独做11天完成总量的1/4。设总量为660，令甲、乙单独、丙的日效率分别为a、b、c，三段方程为6(a＋1.1b)＝165、15(1.1b＋c)＝330、11b＝165。解得b＝15、a＝11、c＝5.5，三人合作日效率为33，工期为20天，对应所给题本的B项。转载题本中20天排在D项。","references":[{"source":"web-80a121fd0142bc49","location":"数量关系，甲乙丙分段合作工程题","quote":"又完成剩余任务量的2/3"}],"evidence":"乙与他人合作时效率比其单独工作时高10%","disposition":"练习技能","basis":"据原题与所列资料编释。"}},"questions":{"国考 2024 副省级 行测#72":{"paper":"国考 2024 副省级 行测","n":72,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",13],"asrc":["a475ecf57d968bc14cd6.pdf",22],"card":"65f7d88efa9d71822a681752","links":[{"id":"k-d3dd3aebd531fc45","role":"解题依据","why":"分段工作量由当段效率和工期确定，合计合作效率时须使用乙在合作状态下的效率。"}]}},"terms":{},"references":{"web-80a121fd0142bc49":{"name":"2024年国家公务员考试行测副省级试题转载PDF","url":"https://gz163rsw.com/Uploads/202409/66dd6d8c1bcaf.pdf"}},"topics":[],"units":{"k-d3dd3aebd531fc45":[["国考 2024 副省级 行测#72"]]}};
